export class ClientDetail {
  private readonly service = inject(ClientService);
  private readonly router = inject(Router);

  /** Bound from the `:id` route parameter. */
  readonly id = input.required<string>();
  protected readonly clientId = computed(() => Number(this.id()));

  protected readonly client = rxResource({
    params: () => this.clientId(),
    stream: ({ params }) => this.service.get(params),
  });

  protected readonly summary = rxResource({
    params: () => this.clientId(),
    stream: ({ params }) => this.service.summary(params),
  });

  /** Which split form is open, if any: a payment received, or the client's held deposits. */
  protected readonly recordingPayment = signal<PaymentSource | null>(null);
  protected readonly paymentSaved = signal(false);
  protected readonly depositApplied = signal(false);
  private readonly paymentForm = viewChild(ClientPaymentForm);
  private readonly depositsPanel = viewChild(ClientDeposits);
  private readonly creditPanel = viewChild(ClientCredit);
  private readonly mergePanel = viewChild(ClientMerge);
  /** Set once the page is being left, so a merge finishing meanwhile does not pull the user back. */
  private leaving = false;

  /** Resolves to true once any payment being recorded, or merge under way, has finished, so the page can be left safely. */
  async canLeave(): Promise<boolean> {
    this.leaving = true;
    await Promise.all([this.paymentForm()?.settled(), this.mergePanel()?.settled()]);
    this.leaving = false;
    return true;
  }

  protected toggle(source: PaymentSource): void {
    this.recordingPayment.update((open) => (open === source ? null : source));
  }

  protected paymentRecorded(source: PaymentSource): void {
    this.recordingPayment.set(null);
    this.paymentSaved.set(source === 'payment');
    this.depositApplied.set(source === 'deposit');
    // A payment may use up the client's credit or leave some over as credit, so both panels can change.
    this.depositsPanel()?.reload();
    this.creditPanel()?.reload();
    this.client.reload();
  }

  protected creditRefunded(): void {
    this.depositsPanel()?.reload();
  }

  protected contactAdded(): void {
    this.summary.reload();
    // The first contact added becomes the main contact.
    if (!this.client.value()?.primaryContact) {
      this.client.reload();
    }
  }

  protected currencyChanged(client: Client): void {
    this.client.set(client);
  }

  protected clientMerged(kept: Client): void {
    // This client no longer exists; carry on at the one it was merged into, unless the user is already leaving.
    if (this.leaving) {
      return;
    }
    void this.router.navigate(['/clients', kept.id]);
  }

  protected primaryChanged(contact: Contact): void {
    this.client.update((c) => c && { ...c, primaryContact: { id: contact.id, name: contact.name } });
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

/** A currency a client can be billed in, by ISO 4217 code; the known ones come from the currency service. */
export type CurrencyCode = string;

export interface Client {
  id: number;
  name: string;
  email: string;
  /** A number to reach the client on; null when not known. */
  phone: string | null;
  /** The client's tax registration number; null when they are not tax registered. */
  taxNumber: string | null;
  /** Where the client's bills are sent; null when not known. */
  billingAddress: string | null;
  /** Whether the client's prices already include tax, so it is worked back out of them rather than added on. */
  taxInclusive: boolean;
  /** Whether the client is tax exempt, so none of their invoices carry any tax whatever the lines say. */
  taxExempt: boolean;
  /** Whether the client is one of the office's key accounts, marked out wherever they are listed. */
  keyAccount: boolean;
  /** The client's standard discount, a percentage each new invoice for them starts with; 0 when none. */
  defaultDiscountPct: number;
  archived: boolean;
  /** The client's main contact; null until one is chosen. */
  primaryContact: { id: number; name: string } | null;
  /** The currency the client is billed in; all of their money is shown in it. */
  currency: CurrencyCode;
  /** What is left to pay on the client's sent, not yet fully paid invoices, in their currency. */
  outstanding: number;
}

/** At-a-glance counts of what one client has. */
export interface ClientSummary {
  projectCount: number;
  contactCount: number;
  lifetimeBilled: number;
}

export type NewClient = Omit<Client, 'id' | 'archived' | 'primaryContact' | 'currency' | 'outstanding'>;

@Injectable({ providedIn: 'root' })
export class ClientService {
  private readonly http = inject(HttpClient);

  list(includeArchived = false): Observable<Client[]> {
    return this.http.get<Client[]>('/api/clients', { params: { includeArchived } });
  }

  get(id: number): Observable<Client> {
    return this.http.get<Client>(`/api/clients/${id}`);
  }

  summary(id: number): Observable<ClientSummary> {
    return this.http.get<ClientSummary>(`/api/clients/${id}/summary`);
  }

  create(client: NewClient): Observable<Client> {
    return this.http.post<Client>('/api/clients', client);
  }

  update(id: number, client: NewClient): Observable<Client> {
    return this.http.put<Client>(`/api/clients/${id}`, client);
  }

  changeCurrency(id: number, currency: CurrencyCode): Observable<Client> {
    return this.http.put<Client>(`/api/clients/${id}/currency`, { currency });
  }

  /** Merges the client into another one, which keeps everything the client had; the client is removed. */
  merge(id: number, targetId: number): Observable<Client> {
    return this.http.post<Client>(`/api/clients/${id}/merge`, { targetId });
  }

  archive(id: number): Observable<Client> {
    return this.http.post<Client>(`/api/clients/${id}/archive`, null);
  }

  restore(id: number): Observable<Client> {
    return this.http.post<Client>(`/api/clients/${id}/restore`, null);
  }
}

